import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Common Foldergram issues and the exact implementation details behind them.","frontmatter":{"title":"Troubleshooting","description":"Common Foldergram issues and the exact implementation details behind them."},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1793727298000}'),r={name:"troubleshooting.md"};function s(n,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="the-app-says-the-library-storage-is-unavailable" tabindex="-1">The app says the library storage is unavailable <a class="header-anchor" href="#the-app-says-the-library-storage-is-unavailable" aria-label="Permalink to &quot;The app says the library storage is unavailable&quot;">​</a></h2><p>Foldergram checks the configured:</p><ul><li>gallery directory</li><li>thumbnails directory</li><li>previews directory</li></ul><p>If any of those are unavailable, the UI reports the reason exposed by the backend.</p><p>Check:</p><ul><li>the configured paths in <code>.env</code></li><li>whether those paths exist</li><li>whether <code>DB_DIR</code>, <code>THUMBNAILS_DIR</code>, and <code>PREVIEWS_DIR</code> are writable by the current process</li><li>whether <code>&lt;DATA_ROOT&gt;/scan-errors</code> is writable if you use <code>SCAN_MEDIA_ERROR_MODE=skip</code></li></ul><p><code>GALLERY_ROOT</code> is scanned read-only. It does not need write access unless you use delete actions that remove originals from the gallery.</p><h2 id="the-database-keeps-resetting" tabindex="-1">The database keeps resetting <a class="header-anchor" href="#the-database-keeps-resetting" aria-label="Permalink to &quot;The database keeps resetting&quot;">​</a></h2><p>If <code>DB_DIR</code> is unavailable, Foldergram falls back to an in-memory SQLite database. That means indexed state disappears when the process stops.</p><p>Fix the configured database directory first.</p><h2 id="folders-load-but-images-or-videos-report-permission-denied" tabindex="-1">Folders load but images or videos report permission denied <a class="header-anchor" href="#folders-load-but-images-or-videos-report-permission-denied" aria-label="Permalink to &quot;Folders load but images or videos report permission denied&quot;">​</a></h2><p>Files can be indexed even when the server cannot read their cached thumbnails or previews. Check the API response or server log for <code>EACCES</code> and the affected path. The server account needs read access to media files and read, write, and directory traversal access to <code>THUMBNAILS_DIR</code> and <code>PREVIEWS_DIR</code>.</p><p>On Linux or WSL, if the server account owns the generated cache directories, restore owner access with your configured paths:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u+rwX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/data/thumbnails</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/data/previews</span></span></code></pre></div><p>This changes permissions on generated caches. It does not require rescanning the library or rebuilding the database. If access is still denied on a Windows-mounted drive, check the Windows permissions for those paths as well.</p><h2 id="startup-stops-after-an-upgrade" tabindex="-1">Startup stops after an upgrade <a class="header-anchor" href="#startup-stops-after-an-upgrade" aria-label="Permalink to &quot;Startup stops after an upgrade&quot;">​</a></h2><p>Foldergram now runs pending SQLite migrations before it serves requests. If the app stops during startup, check the server or container logs first.</p><p>Check:</p><ul><li>whether <code>DB_DIR</code> still exists and is writable</li><li>whether the database volume or bind mount still points to the intended location</li><li>whether the filesystem has enough free space for the SQLite update</li></ul><p>For source installs, you can rerun the migration step directly with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>Foldergram can automatically resume known migrations that were recorded before their schema work began. If the log instead reports a partially present schema, do not delete the database; restore a known-good <code>gallery.sqlite</code> backup and retry the upgrade.</p><h2 id="startup-reports-database-is-locked-and-the-app-keeps-loading" tabindex="-1">Startup reports <code>database is locked</code> and the app keeps loading <a class="header-anchor" href="#startup-reports-database-is-locked-and-the-app-keeps-loading" aria-label="Permalink to &quot;Startup reports \`database is locked\` and the app keeps loading&quot;">​</a></h2><p>This is a SQLite lock error. If it stops the API process, the development client may also report <code>ECONNRESET</code> or <code>ECONNREFUSED</code> for <code>/api/</code> requests.</p><p>Close other Foldergram instances and database tools that have the same <code>&lt;DB_DIR&gt;/gallery.sqlite</code> open, then restart Foldergram. A database viewer with an unfinished read transaction can also block a write. Do not delete the database or its journal files to clear a lock.</p><p>Foldergram allows up to five seconds for temporary SQLite locks during startup migrations, startup schema checks, and normal database access. A persistent lock can still prevent startup; close the process holding it before restarting.</p><p>File-backed databases use WAL mode with <code>synchronous=NORMAL</code>. While the app is running, you may see <code>gallery.sqlite-wal</code> and <code>gallery.sqlite-shm</code> beside the database. That is normal; a clean shutdown checkpoints and releases them. If shutdown logs <code>SQLite WAL checkpoint incomplete</code>, another connection prevented the checkpoint. Close that connection and restart and stop Foldergram, or keep the WAL sidecars with any database backup. Do not delete those files to clear a lock.</p><p>Keep <code>DB_DIR</code> on a local filesystem inside the host. WAL requires reliable shared-memory and file-locking behavior, so avoid NFS, SMB, or other network mounts for the database unless you have validated SQLite locking on that storage. The gallery and generated derivative directories can still live on a separate or network mount.</p><p>Changing between Windows and WSL paths can trigger gallery relocation validation even when both paths refer to the same library. Foldergram updates the cached source paths in one transaction. A failed path update rolls back the entire batch.</p><p>For WSL installations with recurring lock problems or slow database reads on a Windows-mounted drive, you can keep the database on the Linux filesystem while leaving media on the Windows drive. Setting only <code>DATA_ROOT</code> to a path under <code>/mnt/c</code> or <code>/mnt/d</code> also places the database there unless <code>DB_DIR</code> is set separately. Windows-mounted storage adds overhead to SQLite reads from Linux; <a href="https://learn.microsoft.com/en-us/windows/wsl/filesystems#file-storage-and-performance-across-file-systems" target="_blank" rel="noreferrer">Microsoft recommends the WSL filesystem for Linux workloads</a>.</p><p>Stop all processes using the database, back it up, copy the existing database to the new directory, and set <code>DB_DIR</code> in <code>.env</code> to that directory before restarting. Preserve any <code>gallery.sqlite-wal</code>, <code>gallery.sqlite-shm</code>, or <code>gallery.sqlite-journal</code> files with the database if they remain after shutdown; do not copy an actively used database.</p><h2 id="settings-reports-a-permanent-deletion-recovery-warning" tabindex="-1">Settings reports a permanent deletion recovery warning <a class="header-anchor" href="#settings-reports-a-permanent-deletion-recovery-warning" aria-label="Permalink to &quot;Settings reports a permanent deletion recovery warning&quot;">​</a></h2><p>Foldergram retries unfinished permanent deletions at startup and before later maintenance work. If one journal cannot be restored or cleaned safely, its quarantined files and journal are left untouched. The failure is logged and shown in Settings, but it does not prevent the server from starting or the rest of the library from being used.</p><p>Do not manually delete the named journal or quarantine files unless you have first decided whether the affected post should be restored or permanently removed. A later recovery attempt can still use those files.</p><h2 id="nothing-is-being-indexed" tabindex="-1">Nothing is being indexed <a class="header-anchor" href="#nothing-is-being-indexed" aria-label="Permalink to &quot;Nothing is being indexed&quot;">​</a></h2><p>Start with the gallery structure rules:</p><ul><li>files directly inside <code>GALLERY_ROOT</code> are ignored</li><li>hidden folders are ignored</li><li>a regular <code>.nofoldergram</code> file in a folder or any ancestor below <code>GALLERY_ROOT</code> excludes that entire subtree</li><li>a folder is indexed when it directly contains supported media</li><li>in reserved carousel mode, a folder is also indexed when <code>carousels/</code> has an immediate child containing supported media directly</li></ul><p>This will not be indexed:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gallery/</span></span>
<span class="line"><span>  loose-file.jpg</span></span>
<span class="line"><span>  trips/</span></span>
<span class="line"><span>    oslo/</span></span>
<span class="line"><span>      notes.txt</span></span></code></pre></div><p>This will be indexed:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gallery/</span></span>
<span class="line"><span>  trips/</span></span>
<span class="line"><span>    oslo/</span></span>
<span class="line"><span>      IMG_0001.jpg</span></span></code></pre></div><h2 id="rescan-returns-a-rebuild-required-message" tabindex="-1">Rescan returns a rebuild-required message <a class="header-anchor" href="#rescan-returns-a-rebuild-required-message" aria-label="Permalink to &quot;Rescan returns a rebuild-required message&quot;">​</a></h2><p>This happens when the configured gallery root no longer validates against the existing indexed library.</p><p>If you moved the same library to a new location and every indexed file still exists at the same relative path with the same size, mtime, and extension, Foldergram refreshes stored source paths automatically at startup and keeps the existing index.</p><p>Use Settings or <code>POST /api/admin/rebuild-index</code> only when the new root is a different or incomplete library, or when relocation validation already failed.</p><h2 id="places-do-not-appear" tabindex="-1">Places do not appear <a class="header-anchor" href="#places-do-not-appear" aria-label="Permalink to &quot;Places do not appear&quot;">​</a></h2><p>Places are opt-in and only work for photos that already have GPS metadata.</p><p>Check:</p><ul><li><code>Settings -&gt; Places</code> has prepared the offline GeoNames dataset</li><li><code>Settings -&gt; Places</code> has run <code>Rebuild place assignments</code></li><li>the source photos actually contain GPS EXIF coordinates</li></ul><p>Videos and photos without GPS metadata do not appear in Places.</p><h2 id="i-moved-files-into-different-folders-and-expected-them-to-stay-the-same-post" tabindex="-1">I moved files into different folders and expected them to stay the same post <a class="header-anchor" href="#i-moved-files-into-different-folders-and-expected-them-to-stay-the-same-post" aria-label="Permalink to &quot;I moved files into different folders and expected them to stay the same post&quot;">​</a></h2><p>After the derivative-layout upgrade migration has completed, full rescans can preserve the same indexed row, likes, and derivative paths for safe file moves.</p><p>Check:</p><ul><li>that a full scan has already completed since the upgrade</li><li>that the moved file kept the same size and modification time</li><li>that the old source path is genuinely gone, not duplicated</li></ul><p>If a move is ambiguous, Foldergram falls back to the older delete-and-new behavior to avoid matching the wrong file.</p><h2 id="old-thumbnails-or-previews-are-still-on-disk-after-files-disappeared" tabindex="-1">Old thumbnails or previews are still on disk after files disappeared <a class="header-anchor" href="#old-thumbnails-or-previews-are-still-on-disk-after-files-disappeared" aria-label="Permalink to &quot;Old thumbnails or previews are still on disk after files disappeared&quot;">​</a></h2><p>Missing originals are soft-deleted first. Stale derivatives are cleaned up only after the retention window on a later successful full scan.</p><p>That is intentional so temporary share outages or accidental moves do not immediately delete cached derivatives.</p><p>Obsolete playable video previews for qualifying direct-playback videos are a separate cleanup. <strong>Scan and repair derivatives</strong> removes them after validating the current source, live derivative references, and active share requirements. Quick scans do not remove them.</p><h2 id="a-scan-failed-or-completed-with-errors-on-a-corrupt-or-unreadable-media-file" tabindex="-1">A scan failed or completed with errors on a corrupt or unreadable media file <a class="header-anchor" href="#a-scan-failed-or-completed-with-errors-on-a-corrupt-or-unreadable-media-file" aria-label="Permalink to &quot;A scan failed or completed with errors on a corrupt or unreadable media file&quot;">​</a></h2><p>Foldergram can now handle this in two different ways, depending on <code>SCAN_MEDIA_ERROR_MODE</code>.</p><p>Default behavior:</p><ul><li><code>SCAN_MEDIA_ERROR_MODE=skip</code> reports supported-media failures and continues scanning the rest of the library</li><li>the completed run is marked <code>completed_with_errors</code></li><li><code>Settings -&gt; Scan &amp; Library</code> shows the admin-only report path for that run</li><li>the full per-run report is written under <code>&lt;DATA_ROOT&gt;/scan-errors/</code></li></ul><p>Strict behavior:</p><ul><li><code>SCAN_MEDIA_ERROR_MODE=fail</code> stops on the first supported-media failure and marks the scan as failed</li></ul><p>This applies to supported media that reaches scan processing, including supported images and videos. Unsupported extensions, excluded folders, hidden paths, and files placed directly in <code>GALLERY_ROOT</code> are still ignored before this stage.</p><h2 id="a-video-preview-fails-or-an-old-cached-preview-will-not-play" tabindex="-1">A video preview fails or an old cached preview will not play <a class="header-anchor" href="#a-video-preview-fails-or-an-old-cached-preview-will-not-play" aria-label="Permalink to &quot;A video preview fails or an old cached preview will not play&quot;">​</a></h2><p>For source installs, make sure both <code>ffmpeg</code> and <code>ffprobe</code> are available to the server process. Docker images include them.</p><p>Foldergram selects the first audio track whose codec has a decoder in the installed FFmpeg build, skipping unsupported tracks before it. A video with no audio remains silent. If audio exists but no track has an available decoder, preview generation reports an error. Check the scan error report for details; an available decoder does not guarantee that a damaged track can be decoded.</p><p>Empty cached thumbnails and previews are treated as missing. Run <strong>Scan and repair derivatives</strong> to repair them in eager mode, or request the media again in lazy mode. Nonempty corrupt or truncated previews still require forced regeneration; Foldergram does not probe every cached video on each request. <strong>Regenerate Thumbnails</strong> only rebuilds thumbnails and video posters, so it does not repair a nonempty corrupt video preview.</p><p>A missing video preview is expected for a qualifying direct-playback video. Normal playback uses the original, and the old preview URL resolves to it.</p><p>See <a href="/media-processing#video-preview-generation">Video preview generation</a> for audio selection, output validation, and cache behavior.</p><h2 id="a-video-preview-disappears-after-a-repair-scan" tabindex="-1">A video preview disappears after a repair scan <a class="header-anchor" href="#a-video-preview-disappears-after-a-repair-scan" aria-label="Permalink to &quot;A video preview disappears after a repair scan&quot;">​</a></h2><p>If the video qualifies for direct playback, its generated preview is no longer needed for normal playback. <strong>Scan and repair derivatives</strong> removes only that generated preview file after validating the source and share requirements. Thumbnails, originals, and indexed identities are preserved.</p><p>If a folder share still needs scoped preview media, the preview is retained or recreated. Enabling sharing later also works without a library rebuild because the scoped share route can generate the required preview on authorized first access.</p><p>If you later run an older Foldergram version that expects generated video previews by default, use <strong>Scan and repair derivatives</strong> to regenerate them. Lazy mode can also recover them on demand. Originals and indexed identities are not affected.</p><h2 id="moments-are-missing-and-highlights-appear-instead" tabindex="-1">Moments are missing and highlights appear instead <a class="header-anchor" href="#moments-are-missing-and-highlights-appear-instead" aria-label="Permalink to &quot;Moments are missing and highlights appear instead&quot;">​</a></h2><p>That is expected when the library does not have enough EXIF-backed timestamps.</p><p>Foldergram switches to Highlights unless it has:</p><ul><li>at least <code>24</code> indexed posts</li><li>at least <code>18</code> EXIF-backed posts</li><li>at least <code>30%</code> EXIF coverage</li></ul><h2 id="a-folder-named-stories-stopped-appearing-as-a-normal-album" tabindex="-1">A folder named <code>stories</code> stopped appearing as a normal album <a class="header-anchor" href="#a-folder-named-stories-stopped-appearing-as-a-normal-album" aria-label="Permalink to &quot;A folder named \`stories\` stopped appearing as a normal album&quot;">​</a></h2><p>That is expected when Foldergram is using the default reserved-stories mode.</p><p>In that mode, <code>AppFolder/stories</code> is reinterpreted as folder-story data instead of a standalone app folder.</p><p>If you want folders literally named <code>stories</code> to remain ordinary app folders:</p><ol><li>open <code>Settings -&gt; General Settings</code></li><li>enable <code>Treat stories folders as normal app folders</code></li><li>save the change</li><li>run a scan from <code>Settings -&gt; Scan &amp; Library</code></li></ol><h2 id="a-folder-is-still-showing-up-after-i-excluded-it" tabindex="-1">A folder is still showing up after I excluded it <a class="header-anchor" href="#a-folder-is-still-showing-up-after-i-excluded-it" aria-label="Permalink to &quot;A folder is still showing up after I excluded it&quot;">​</a></h2><p>Folder exclusions can come from:</p><ul><li><code>GALLERY_EXCLUDED_FOLDERS</code> in <code>.env</code> or Docker Compose</li><li>custom rules in <code>Settings -&gt; General Settings</code></li><li>a regular file named exactly <code>.nofoldergram</code> inside the folder or an ancestor below <code>GALLERY_ROOT</code></li></ul><p>Check:</p><ul><li>rules without a slash match folder names anywhere in the gallery tree</li><li>rules with a slash match one exact relative path below <code>GALLERY_ROOT</code></li><li>env-backed rules require a restart to change</li><li>custom rules require <code>Save changes</code>, then a full scan from <code>Settings -&gt; Scan &amp; Library</code></li><li><code>.nofoldergram</code> must be a regular file, rather than a directory or symlink; a marker directly in <code>GALLERY_ROOT</code> is ignored</li><li>adding or removing markers triggers a debounced scan only in development mode; Docker and other production deployments require a manual full scan</li></ul><p>If the folder was already indexed before the rule existed, it will stay visible until that scan finishes and soft-removes it from the index.</p><p>If an expected folder is missing, check it and its ancestors for <code>.nofoldergram</code>, as well as environment and Settings exclusions. Remove the marker and run a full scan to restore matching index records. The same check applies to missing story capsules and carousel posts.</p><h2 id="videos-or-animated-avif-files-fail-to-index-or-generate-previews" tabindex="-1">Videos or animated AVIF files fail to index or generate previews <a class="header-anchor" href="#videos-or-animated-avif-files-fail-to-index-or-generate-previews" aria-label="Permalink to &quot;Videos or animated AVIF files fail to index or generate previews&quot;">​</a></h2><p>Check that both tools are installed and available on <code>PATH</code>:</p><ul><li><code>ffprobe</code></li><li><code>ffmpeg</code></li></ul><p>Foldergram uses them directly for supported video files and animated AVIF image-sequence processing. Static AVIF files use the normal image path and do not require these tools.</p><h2 id="a-video-opens-from-the-original-file-instead-of-a-generated-preview" tabindex="-1">A video opens from the original file instead of a generated preview <a class="header-anchor" href="#a-video-opens-from-the-original-file-instead-of-a-generated-preview" aria-label="Permalink to &quot;A video opens from the original file instead of a generated preview&quot;">​</a></h2><p>That is a normal optimization. Foldergram streams the original file directly when the video is already suitable for browser playback under the current size and codec rules.</p><p>The current policy requires a compatible <code>.mp4</code> with H.264 video, <code>yuv420p</code> pixels, AAC or no audio, a known size of at most <code>24 MiB</code>, and a known orientation-correct display width of at most <code>1500</code> pixels. Larger compatible videos use a generated preview and can still offer the HD original switch.</p><p>Folder-share visitors never receive ordinary original access. Shared playback continues to use scoped preview media, which may be generated even for a video that normally plays from its original.</p><p>See <a href="/media-processing">Media Processing</a> for the exact conditions.</p><h2 id="video-seeking-is-slow-or-playback-stalls-behind-a-reverse-proxy" tabindex="-1">Video seeking is slow or playback stalls behind a reverse proxy <a class="header-anchor" href="#video-seeking-is-slow-or-playback-stalls-behind-a-reverse-proxy" aria-label="Permalink to &quot;Video seeking is slow or playback stalls behind a reverse proxy&quot;">​</a></h2><p>Foldergram serves original media with <code>ETag</code>, <code>Last-Modified</code>, <code>Accept-Ranges</code>, and revalidation-friendly <code>Cache-Control</code> headers. The browser should revalidate metadata and request bounded byte ranges while seeking.</p><p>If seeking works directly but fails through a reverse proxy:</p><ul><li>forward <code>Range</code>, <code>If-Range</code>, <code>If-None-Match</code>, <code>If-Modified-Since</code>, <code>Cookie</code>, and <code>Host</code></li><li>allow <code>206 Partial Content</code> responses through</li><li>avoid buffering long video responses when the proxy supports streaming controls</li><li>remove rules that ignore Foldergram&#39;s <code>Cache-Control</code> headers on protected endpoints</li><li>do not cache API responses by URL alone when cookies or folder-share grants affect access</li><li>do not alias <code>/thumbnails</code> or <code>/previews</code> to their filesystem directories without equivalent authorization</li><li>test against Foldergram directly to separate proxy behavior from the app</li></ul><p>Direct connections remain fully supported.</p><p>See <a href="/security#reverse-proxy-deployments">Security</a> and <a href="/configuration#reverse-proxy-deployments">Configuration</a>.</p><h2 id="the-development-watcher-is-not-reacting" tabindex="-1">The development watcher is not reacting <a class="header-anchor" href="#the-development-watcher-is-not-reacting" aria-label="Permalink to &quot;The development watcher is not reacting&quot;">​</a></h2><p>The watcher is not a permanent always-on background process for every startup path. It is development-only and is started by the scan and rebuild flows.</p><p>If needed:</p><ol><li>run a manual scan from Settings</li><li>make your filesystem change again</li></ol><h2 id="likes-disappeared-after-a-rebuild" tabindex="-1">Likes disappeared after a rebuild <a class="header-anchor" href="#likes-disappeared-after-a-rebuild" aria-label="Permalink to &quot;Likes disappeared after a rebuild&quot;">​</a></h2><p>That is expected for <code>Rebuild Library Index</code>. The rebuild resets the indexed library tables, including <code>likes</code>.</p><p>Thumbnail-only rebuilds do not clear likes.</p><h2 id="docs-build-fails" tabindex="-1">Docs build fails <a class="header-anchor" href="#docs-build-fails" aria-label="Permalink to &quot;Docs build fails&quot;">​</a></h2><p>Use the root command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:docs</span></span></code></pre></div><p>If it fails, check for:</p><ul><li>broken internal links</li><li>invalid frontmatter</li><li>mistakes in <code>docs/.vitepress/config.ts</code></li></ul><h2 id="the-app-still-behaves-oddly-in-development-after-frontend-changes" tabindex="-1">The app still behaves oddly in development after frontend changes <a class="header-anchor" href="#the-app-still-behaves-oddly-in-development-after-frontend-changes" aria-label="Permalink to &quot;The app still behaves oddly in development after frontend changes&quot;">​</a></h2><p>The client actively unregisters previously installed service workers in development. Reload once after startup if you previously visited a production build from the same origin and the browser still has stale cached assets.</p><h2 id="carousel-scan-warnings-and-reconciliation-recovery" tabindex="-1">Carousel scan warnings and reconciliation recovery <a class="header-anchor" href="#carousel-scan-warnings-and-reconciliation-recovery" aria-label="Permalink to &quot;Carousel scan warnings and reconciliation recovery&quot;">​</a></h2><p>Structural carousel warnings appear in <strong>Settings → Scan &amp; Library</strong> without turning a successful scan into a processing failure. Move media placed directly in <code>carousels/</code> into a child folder; move nested media directly into that post child; split posts above 20 items; and expect a one-item child to become a normal post with a warning. If carousel children appear as ordinary folders, disable <strong>Treat carousels folders as normal app folders</strong>, save, then run <strong>Scan for changes</strong>.</p><p>After changing the carousel folder setting, follow the pending update message in <strong>Settings → Scan &amp; Library</strong>. Run <strong>Scan for changes</strong> to apply the saved mode, or use <strong>Rebuild Library Index</strong> when Settings reports that a rebuild is required. The reminder remains visible until the index reflects the selected mode.</p>`,125)])])}const g=a(r,[["render",s]]);export{u as __pageData,g as default};
